/** 這個項目在 month（1–12）要不要做 */
export const applies = (item, month) => !item.m || Boolean(item.m[month]);

/** 該月清單，依週期排序並分組：[{ f, list: [{ item, index }] }] */
export function tasksForMonth(role, month) {
  const todo = role.items.map((item, index) => ({ item, index })).filter((x) => applies(x.item, month));
  return FREQ_ORDER.map((f) => ({ f, list: todo.filter((x) => x.item.f === f) })).filter((g) => g.list.length);
}

/**
 * 月份橘點：該月（已到或已過的月份）還有必做項目沒勾。未來月份不提醒；選做項目不算。
 * isDone(index) 由畫面提供（查勾選紀錄）。
 */
export function hasPending(role, month, currentMonth, isDone) {
  if (month > currentMonth) return false;
  return role.items.some((it, i) => it.req && applies(it, month) && !isDone(i));
}

/**
 * 依登入角色決定預設分頁。
 * 業者：幸福巴士 1.0／2.0、市區客運；縣府 → 縣府；唯讀單位（監理站／區研中心，沒有應辦事項）→ 總覽。
 */
export function defaultRoleTab(session, operator) {
  if (session.role === 'county') return 't6';
  if (session.role === 'readonly') return 'ov';
  if (operator?.type === 'happybus') return operator.happybusVersion === '2.0' ? 't2' : 't1';
  if (operator) return 't3';
  return 'ov';
}

/** 看得到哪些分頁：業者只看自己單位的分頁；縣府、唯讀單位看全部（含總覽） */
export function visibleTabs(session, operator) {
  if (session.role === 'operator') return [defaultRoleTab(session, operator)];
  return ['ov', ...ROLES.map((r) => r.id)];
}

/** 勾選紀錄的 key（依年、月、分頁、項目） */
export const doneKey = (year, month, roleId, index) => `huabus-task|${year}|${month}|${roleId}|${index}`;
